  'CCDRU': 1,
  'DECRETO': 2,
  'NAO_INFORMADO': 3,
  'PORTARIA': 4,
  'RTID': 5,
  'TITULADO': 6,
  'TITULO_ANULADO': 7,
  'TITULO_PARCIAL': 8,
};

// Função modificada para usar o mapeamento fixo:
function adicionarFaseNumberFixo(collection, map) {
  return collection.map(function(feature) {
    var fase = feature.get('fase');
    // Busca o valor diretamente do objeto de mapeamento fixo
    var faseNumber = map[fase]; 
    return feature.set('faseNumber', faseNumber);
  });
}
```

**Recomendação:** Use a **primeira solução** (`adicionarFaseNumber`) se a ordem **alfabética/lexicográfica** for aceitável. Use a **segunda solução** (`adicionarFaseNumberFixo`) se a ordem for **estritamente definida** (como no seu exemplo: CCDRU=1, DECRETO=2, etc.).

